//! Cross-language conformance: replay the IR-derived oracle against Rust.
//!
//! `ir/oracle.json` is generated by `scripts/gen_oracle.py` from the typed IR.
//! The Lean kernel checks every vector against the Lean `allocate`
//! (`ir/Oracle.lean`), and `ir/Refinement.lean` proves the IR transition equals
//! the Lean `allocate` for all inputs. This test closes the chain on the same
//! bounded domain: Rust agrees with Lean, and therefore with the IR, on every
//! vector. It is bounded testing, not a proof for all inputs.

use driverpass_poc::domain::{allocate, Decision, Roster};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Vector {
    name: String,
    before: Roster,
    slot_id: i64,
    expected: Expected,
}

#[derive(Debug, Deserialize)]
struct Expected {
    decision: Decision,
    roster: Roster,
}

fn vectors() -> Vec<Vector> {
    serde_json::from_str(include_str!("../../ir/oracle.json")).expect("valid oracle JSON")
}

#[test]
fn rust_matches_ir_oracle() {
    let vectors = vectors();
    // Guard against an accidentally emptied or truncated oracle.
    assert_eq!(vectors.len(), 850, "oracle size changed; regenerate and review");
    let mut failures = Vec::new();
    for v in &vectors {
        let (roster, decision) = allocate(&v.before, v.slot_id);
        if decision != v.expected.decision || roster != v.expected.roster {
            failures.push(format!(
                "{}: expected {:?} {:?}, got {:?} {:?}",
                v.name, v.expected.decision, v.expected.roster, decision, roster
            ));
        }
    }
    assert!(failures.is_empty(), "{} of {} vectors differ:\n{}",
        failures.len(), vectors.len(), failures.join("\n"));
}

#[test]
fn oracle_covers_every_decision() {
    let vectors = vectors();
    for d in [Decision::Accepted, Decision::OffDuty, Decision::Duplicate] {
        assert!(vectors.iter().any(|v| v.expected.decision == d), "no {:?} vector", d);
    }
}
